import React from "react";
import Slider from "react-slick"; // Slider kullanımı için react-slick kütüphanesini ekliyoruz.

function EventsSlider() {
  const settings = {
    dots: true, // Pagination dots
    arrows: true, // Arrows for next/prev slides
    infinite: true, // Continuous loop
    autoplay: true, // Autoplay slides
    autoplaySpeed: 2000, // Autoplay speed in milliseconds
    slidesToShow: 1, // Only one slide visible at a time
    slidesToScroll: 1, // Scroll one slide per swipe
  };

  return (
    <div style={styles.wrapper}>
      {/* Slider component */}
      <Slider {...settings}>
        {/* Single Slide */}
        <div style={styles.contentBox}>
          <img
            src="https://www.techcareer.net/_next/image?url=https%3A%2F%2Fcdn.gcp.techcareer.net%2F1112_412_2_cd52574011%2F1112_412_2_cd52574011.png&w=1200&q=100"
            alt="Slide 1"
            style={styles.image}
          />
        </div>
      </Slider>

      {/* Alt kısımdaki mavi bar */}
      <div style={styles.bottomBar}></div>
    </div>
  );
}

const styles = {
  wrapper: {
    position: "relative",
    width: "1024px", // Slider genişliği
    marginTop: "50px",
    marginLeft: "auto", // Ortalamak için
    marginRight: "auto", // Ortalamak için
    backgroundColor: "rgb(246, 248, 255)", // Slider arka plan rengi
  },

  contentBox: {
    width: "987px", // İçerik genişliği
    height: "400px",
    backgroundColor: "#293349",
    borderRight: "15px solid #00C26D",
    borderBottom: "15px solid #00C26D",
    display: "flex", // Görseli ortalamak için
    justifyContent: "center", // Görseli ortalamak için
    alignItems: "center", // Görseli ortalamak için
    padding: "10px",
    overflow: "hidden",
    margin: "0 auto", // Center the contentBox horizontally
  },

  image: {
    width: "100%", // Görselin genişliği %100
    height: "auto", // Görselin yüksekliği otomatik ayar
    objectFit: "cover", // Görsellerin oranını bozmadan görünmesini sağlarız
    borderRadius: "5px", // Köşeleri yuvarlamak
  },

  bottomBar: {
    width: "100%", // Full width
    height: "100px",
    backgroundColor: "#293349", // Alt mavi bar rengi
    marginTop: "20px", // Slider ve bar arasına boşluk
  },
};

export default EventsSlider;
